        .chart-caption { font-size: 0.9em; color: #64748b; margin-top: 10px; font-style: italic; }
        .insight-box { background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%); border-left: 4px solid #2563eb; padding: 20px; border-radius: 8px; margin: 15px 0; }
        .insight-box h4 { color: #1e3a5f; margin-bottom: 8px; }
        .warning-box { background: #fef3c7; border-left: 4px solid #f59e0b; padding: 15px; border-radius: 8px; margin: 15px 0; }
        .topic-tag { display: inline-block; background: #dbeafe; color: #1e3a5f; padding: 4px 10px; border-radius: 15px; font-size: 0.85em; margin: 3px; }
        .summary-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; margin: 20px 0; }
        .summary-item { text-align: center; padding: 15px; background: #f8fafc; border-radius: 8px; }
        .summary-item .num { font-size: 1.8em; font-weight: 700; color: #2563eb; }
        .summary-item .label { font-size: 0.85em; color: #64748b; }
        footer { text-align: center; padding: 30px; color: #64748b; font-size: 0.9em; }
        .toc { background: #f1f5f9; padding: 25px; border-radius: 10px; margin-bottom: 25px; }
        .toc ul { list-style: none; }
        .toc li { margin: 8px 0; }
        .toc a { color: #2563eb; text-decoration: none; }
        .toc a:hover { text-decoration: underline; }
        .highlight { background: #fef3c7; padding: 2px 6px; border-radius: 4px; }
    </style>
